#include "../include/client.hpp"

void st_m(std::string a, int* m) {
    int l = 0, r = 0, raz = 0;
    for(int i = 0; i < a.length(); i++) {
        if (a[i] != ' ') {
            r = i;
        }
        else {
            r = i;
            int y = stoi(a.substr(l, r - l));
            m[raz] = y;
            l = i + 1;
            raz++;
        }
    }
}

int razmer(std::string s) {
    int r = 0;
    for(int i = 0; i < s.length(); i++) {
        if(s[i] == ' ') {
            r++;
        }
    }
    return r;
}

void sh(const std::string &sl, char c, int* m) {
    for(int i = 0; i < sl.length(); i++) {
        int t = (int)(c xor sl[i]);
        m[i] = t;
    }
}

std::string ch_st(char* m) {
    int i = 0;
    std::string otv = "";
    while (m[i] != '\0') {
        otv += m[i];
        i++;
    }
    return otv;
}

Cl::Cl() : clsoc(INVALID_SOCKET) {}

Cl::~Cl() {
    if (clsoc != INVALID_SOCKET) {
        closesocket(clsoc);
        WSACleanup();
    }
}

void Cl::connServ(const char* serverAddress, int port) {
    WSADATA wsaData;
    struct sockaddr_in serverAddr;

    WSAStartup(MAKEWORD(2, 2), &wsaData);
    clsoc = socket(AF_INET, SOCK_STREAM, 0);

    serverAddr.sin_family = AF_INET;
    serverAddr.sin_addr.s_addr = inet_addr(serverAddress);
    serverAddr.sin_port = htons(port);

    connect(clsoc, (struct sockaddr*)&serverAddr, sizeof(serverAddr));
    std::cout << "Connected to server." << std::endl;
}

void Cl::run() {
    std::string sms;
    char buffer[102400]; 
    char code;
    std::cout << "Enter code: ";
    std::cin.get(code);
    std::cin.ignore(std::numeric_limits<std::streamsize>::max(),'\n');
    
    while (true) {
        std::cout << "Enter message: ";
        getline(std::cin, sms, '\n');

        if (sms == "exit") {
            break;
        }

        int mas[sms.length()];
        sh(sms, code, mas);
        std::string sms_sh = m_st(mas,sms.length());
        send(clsoc, sms_sh.c_str(), sms_sh.length(), 0);
        
        auto rsh = [code](int* m, int raz) {
            std::string otv = "";
            for (int i = 0; i < raz; i++) {
                otv += (m[i] ^ code);
            }
            return otv;
        };
        
        int bytesReceived = recv(clsoc, buffer, sizeof(buffer), 0);
        if(bytesReceived>0){
            buffer[bytesReceived] = '\0'; 
            std::string buf_s = ch_st(buffer);
            int mas1[razmer(buf_s)];
            st_m(buf_s,mas1);
            std::string buf_otv = rsh(mas1,razmer(buf_s));
            std::cout << "Received from server: " << buf_otv << std::endl;
        }
    }
    std::cout << "Closing connection." << std::endl;
}

std::string Cl::m_st(int* m, int r) {
    std::string a="";
    for (int i = 0; i < r; i++) {
        a+=std::to_string(m[i]);
        a+=' ';
    }
    return a;
}

AdminCl::AdminCl() : Cl() {}

std::ostream& operator<<(std::ostream& os, const AdminCl& client) {
    os << "[Admin Client | Socket: " << client.clsoc << "]";
    return os;
}

