int AdminCl::isadm(std::string n, std::string p) {
    char buffer1[1024];
    std::string a = "reg_admin "+ n + " " + p;
    send(clsoc, a.c_str(), a.length(), 0);
    int a1 = recv(clsoc, buffer1, sizeof(buffer1), 0);
    buffer1[a1] = '\0'; 
    std::string buf_s1 = ch_st(buffer1);
    int a2 = stoi(buf_s1);
    return a2;
}

std::string AdminCl::m_st(int* m, int r) {
    std::string a="";
    for (int i = 0; i < r; i++) {
        a+=std::to_string(m[i]);
        a+=' ';
    }
    return a;
}
